def add(q,stem,conditions,values,reasons,answer,solution,summary,core='技術士法の義務・責務と適用条件',concept='concept_029',theory='duties',citations=None,ambiguity='',difficulty='2'):
 r=by[q];good=answer.split('|');choices={str(i):{'value':v,'verdict':'適切な解答候補' if str(i) in good else '不適切な解答候補','reason':reason} for i,(v,reason) in enumerate(zip(values,reasons),1)}
 assert len(choices)==5
 images=[f'extracted/pages/{r["source_year_directory"]}/aptitude/page_{p:03}.png' for p in range(int(r['source_page']),int(r['source_page_end'])+1)]
 items.append(dict(question_id=q,source_sha256=r['source_sha256'],stem=stem,conditions=conditions,choices=choices,figures='図なし。組合せ表または個数選択肢は原典画像で確認。',ambiguity=ambiguity,evidence=images,summary=summary,core_concept=core,required_knowledge={'duties':'第44条の信用失墜禁止、第45条の守秘、第45条の2の公益、第46・47条の名称表示、第47条の2の継続的な資質向上。','public':'守秘の対象と存続、公益優先、客観的判断、情報の権利と利益相反。','norms':'社会規範の下位概念としての法規範と倫理規範。','cpd':'CPDは能力向上を目的とする継続研鑚であり、通常業務との区別、実施記録と証拠、制度ごとの運用を確認する。','competency':'平成26年3月の資質能力には専門的学識、問題解決、マネジメント、評価、コミュニケーション、リーダーシップ、技術者倫理がある。'}[theory],solution=solution,independent_answer=answer,answer_reason=summary+' '+solution.split('。')[-2]+'。',learning_points={'duties':'主語、名称表示をする場合という条件、退職後も残る義務を確認する。条文の名称と努力義務の性質を区別する。','public':'公益確保と守秘を対立する二択にせず、情報の性質・危険・適切な相手への説明を検討する。独自調査で権利が自動的に移るとは限らない。','norms':'形式として法であることと、内容として職業倫理を表すことは両立する。','cpd':'勤務時間の経過と能力の向上は別である。学んだ内容と証拠を記録し、対象年度のガイドラインを参照する。','competency':'名称の暗記だけでなく、知識の適用、複合問題への対応、資源配分、成果評価、合意形成、倫理判断の仕事へ対応させる。'}[theory],theory_references=['theory:engineer_act:'+theory],discipline_id='apt_0',concept_id=concept,classification_reason='原典の全記述と5肢を確認。'+core+'が主題であり、環境や利益という単語だけの候補分類を採用しない。',calculation='false',figure='false',law='true' if theory in ['duties','public','norms'] else 'false',evaluation=dict(knowledge_novelty='2',reasoning_steps='2' if difficulty=='2' else '1',calculation_load='0',figure_reading='0',difficulty=difficulty,difficulty_reason='物理専門外の法・職業倫理の知識を確認し、複数の条件を判定する。' if difficulty=='2' else '専門外の語句を知れば一段階で選択できる。'),citations=citations or ['engineer_act_current'],source_reference_date=r['year']))

def table(q,stem,terms,values,reasons,ans,extra='',theory='duties',citations=None,concept='concept_029'):
 add(q,stem,{'空欄順':list(terms),'正しい語句の照合':terms,'出題時資料':extra},values,reasons,ans,'各空欄の主語と見出しから語句を特定する。'+extra+' 条文又は指定資料に一致する語句は、'+'、'.join(terms.values())+'である。ほかの組合せは下記の相違がある。',stem+' 正しい組合せは'+ '／'.join(terms.values())+'である。',theory=theory,citations=citations,concept=concept,difficulty='1')

def judgments(q,statements,truth,reasoning,values,mode='誤り',concept='concept_029',theory='duties',ambiguity='',citations=None):
 count=sum(x==('×' if mode=='誤り' else '○') for x in truth)
 answer=str(values.index(str(count))+1)
 cond={k:{'原典の主張の要約':s,'独立判定':v,'理由':r} for k,s,v,r in zip('アイウエオカキ',statements,truth,reasoning)}
 detail=' '.join(k+'は'+v+'：'+r+'。' for k,v,r in zip('アイウエオカキ',truth,reasoning))
 reasons=[('個別判定を数えると'+mode+'は'+str(count)+'件であり、この数に一致する。') if v==str(count) else ('選択肢は'+v+'件だが、'+mode+'と判定した'+''.join(k for k,t in zip('アイウエオカキ',truth) if t==('×' if mode=='誤り' else '○'))+'の'+str(count)+'件と合わない。') for v in values]
 add(q,'複数の記述について'+mode+'の個数を選ぶ。',cond,[v+'件' for v in values],reasons,answer,detail+' よって'+mode+'は'+str(count)+'件である。',''+mode+'と判定する記述は'+''.join(k for k,t in zip('アイウエオカキ',truth) if t==('×' if mode=='誤り' else '○'))+'で、'+str(count)+'件である。',concept=concept,theory=theory,ambiguity=ambiguity,citations=citations)

def combos(q,statements,truth,reasoning,values,theory='duties',concept='concept_029',citations=None):
 actual=''.join(truth);answer=str(values.index(actual)+1)
 cond={k:{'原典の主張の要約':s,'独立判定':v,'理由':r} for k,s,v,r in zip('アイウエオカキ',statements,truth,reasoning)}
 detail=' '.join(k+'は'+v+'：'+r+'。' for k,v,r in zip('アイウエオカキ',truth,reasoning))
 reasons=[]
 for v in values:
  wrong=[k+'（'+a+'とするが'+b+'）' for k,a,b in zip('アイウエオカキ',v,actual) if a!=b]
  reasons.append('全記述の判断に一致する。' if not wrong else '相違する箇所は'+'、'.join(wrong)+'である。各記述の理由は独立判定に示した。')
 add(q,'各記述の正誤を判定して組合せを選ぶ。',cond,['アから順に'+v for v in values],reasons,answer,detail+' 判定列は'+actual+'である。','アから順に'+actual+'となる。',theory=theory,concept=concept,citations=citations)

combos('H23-REG-APT-01', ['守秘対象を所属組織の取引相手だけに限定する','社会・環境への影響を評価し公衆に危険があれば良心に従って行動する','利益相反情報を雇用者・依頼者へ開示する','営業機密から独自に調査した情報の権利は当事者の協議による'], '×○○○', ['業務上知った秘密は取引相手以外についても対象になる','公益確保のために影響を予測する','判断をゆがめる可能性を関係者に説明する','独自調査だけで一方に帰属すると決め付けない'], ['○×○×','×○×○','○×○○','×○○○','○○○×'],theory='public',citations=['engineer_act_current','cpd_v3'])

